    /**
     * Method to retrieve the Gateway via GatewayFetchOneSummary
     * @param 	summary GatewayFetchOneSummary 
     * @return 	GatewayFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Gateway getGateway( GatewayFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "GatewayFetchOneSummary arg cannot be null" );
    	
    	Gateway entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Gateway
        	// --------------------------------------
        	CompletableFuture<Gateway> futureEntity = queryGateway.query(new FindGatewayQuery( new LoadGatewayFilter( summary.getGatewayId() ) ), ResponseTypes.instanceOf(Gateway.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Gateway with id " + summary.getGatewayId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


